use verus::prelude::*;

verus! {

    /// contains_k returns true iff there is some index j in `arr`
    /// such that arr[j] == k.
    fn contains_k(arr: &Vec<i32>, k: i32) -> (result: bool)
        // Postcondition: result is exactly “there exists an index j < arr.len()
        // with arr[j] == k”.
        ensures
            result <==> exists |j: usize| j < arr@.len() && arr@[j] == k
    {
        let mut i: usize = 0;
        let mut found: bool = false;

        // Loop invariant:
        //   0 ≤ i ≤ arr.len()
        //   found == “there exists j < i such that arr[j] == k”
        // Decreases ensures termination.
        while i < arr.len()
            invariant
                i <= arr.len();
                found <==> exists |j: usize| j < i && arr@[j] == k;
            decreases
                arr.len() - i;
        {
            if arr[i] == k {
                found = true;
                // short-circuit out of the loop
                i = arr.len();
            } else {
                i += 1;
            }
        }

        result = found;
    }

}